import squishtest3 as sq
import test

logger = logging.getLogger(__name__)


# Wrapping the test section in a context manager class
# so it is always called pairwise. i.e endSection for each
# startSection
# to use call function with 'with' keyword
def test_section(text):
    class Testsection:
        def __enter__(self):
            test.startSection(text) #type:ignore

        def __exit__(self, exc_type, exc_value, traceback):
            test.endSection() #type:ignore
    return Testsection()


# XML report generation for VX data, physics verification
def get_xml_report(data):

    try:
        top = Element('top')
        comment = Comment('Physics Verification')
        top.append(comment)

        for i in data:

            before_vx = i[0]
            after_vx = i[1]

            beam = SubElement(top, 'Beam', {"Name": before_vx['BeamName']['P']})
            beam.text = 'Beam Information'

            beam_start = SubElement(beam, 'Section',
                                    {"text": "Linac parameters before delivery"
                                     })

            fields = [
                "PatientId",
                'PatientName',
                'TableIsocRot',
                'Energy',
                'LviTechniqueId',
                'WedgePosition',
                'LviStepMonitorUnit',
                'BeamMonitorUnits',
                'GantryAngle',
                'GantryDirection',
                'CollimatorAngle',
                'CollimatorDirection']

            for i in fields:
                if i not in before_vx.keys():
                    continue
                field = SubElement(beam_start, 'Field', {"Name": i})
                field_value = SubElement(field, 'Value')
                if before_vx[i]['R'] == '':
                    field_value.text = before_vx[i]['P']
                else:
                    field_value.text = before_vx[i]['R']

            beam_start = SubElement(beam, 'Section',
                                    {"text": "Linac parameters after delivery"
                                     })

            for i in fields:
                if i not in after_vx.keys():
                    continue
                field = SubElement(beam_start, 'Field', {"Name": i})
                field_value = SubElement(field, 'Value')
                if after_vx[i]['R'] == '':
                    field_value.text = after_vx[i]['P']
                else:
                    field_value.text = after_vx[i]['R']

        rough_string = ElementTree.tostring(top, 'utf-8')
        reparsed = minidom.parseString(rough_string)
        # print reparsed.toprettyxml(indent="  ")

        with open('output.xml', 'w') as f:
            f.write(reparsed.toprettyxml(indent="  "))

    except Exception as e:
        logger.exception("XML report issue " + str(e))
